import { useState } from 'react'
import { TimeRangePicker, type TimeRangeValue } from 'moru-ui'

export function MeetingTime() {
  const [range, setRange] = useState<TimeRangeValue>({ start: '09:00', end: '10:00' })
  return (
    <TimeRangePicker
      label="Meeting time"
      name="meeting"
      value={range}
      onValueChange={setRange}
      step={15}
    />
  )
}
